CREATE OR REPLACE FUNCTION public.freeze_issued_service_letter() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF OLD.issued_at IS NOT NULL AND (
     NEW.letter_summary IS DISTINCT FROM OLD.letter_summary OR NEW.issued_letter_html IS DISTINCT FROM OLD.issued_letter_html OR
     NEW.subject IS DISTINCT FROM OLD.subject OR NEW.resident_id IS DISTINCT FROM OLD.resident_id OR
     NEW.issued_at IS DISTINCT FROM OLD.issued_at OR NEW.verification_token IS DISTINCT FROM OLD.verification_token) THEN
    RAISE EXCEPTION 'service_request: an issued letter is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status = 'issued' AND OLD.status IS DISTINCT FROM 'issued' THEN NEW.issued_at := now(); END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER zzzz_freeze_issued_service_letter BEFORE UPDATE ON public.service_request FOR EACH ROW EXECUTE FUNCTION public.freeze_issued_service_letter();
